idx = 1
for item in schueco_list:
    tr = item[0].strip()
    ru = item[1].strip()
    cat = item[2].strip()
    lbl = item[3].strip()
    key = tr.lower()
    if key in seen:
        continue
    seen.add(key)
    
    phon = turkish_to_phonetic(tr)
    all_entries.append({
        "id": f"sch_{idx}",
        "tr": tr,
        "phonetic": phon,
        "ru": ru,
        "category": cat,
        "categoryLabel": lbl,
        "isSchueco": True,
        "learned": False
    })
    idx += 1

